package org.biopulse;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.http.MediaType;import org.testcontainers.containers.MySQLContainer;import org.testcontainers.junit.jupiter.*;import org.biopulse.jdbc.Sql;import org.biopulse.dao.*;import org.biopulse.service.*;import org.biopulse.domain.*;import org.biopulse.dto.Requests.*;import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;
@SpringBootTest(properties={"biopulse.seed-demo=true","biopulse.demo-password=IntegrationOnlyPassword!"}) @AutoConfigureMockMvc
class ApplicationIT {
 static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.4");
 @DynamicPropertySource static void db(DynamicPropertyRegistry r){
  String url=System.getenv("TEST_DB_URL");
  if(url==null||url.isBlank()){mysql.start();r.add("spring.datasource.url",mysql::getJdbcUrl);r.add("spring.datasource.username",mysql::getUsername);r.add("spring.datasource.password",mysql::getPassword);}
  else {r.add("spring.datasource.url",()->url);r.add("spring.datasource.username",()->System.getenv("TEST_DB_USER"));r.add("spring.datasource.password",()->System.getenv("TEST_DB_PASSWORD"));}
 }
 @Autowired MockMvc mvc;@Autowired RegistryDao registry;@Autowired MeasurementDao measurements;@Autowired MeasurementIngestionService ingestion;@Autowired AlertService alerts;@Autowired AlertDao alertDao;@Autowired Sql sql;@Autowired ObjectMapper json;@Autowired SimulationService simulations;
 @Test void healthAndAuthentication()throws Exception{mvc.perform(get("/api/v1/health")).andExpect(status().isOk());mvc.perform(get("/api/v1/patients")).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/session").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin@biopulse.local\",\"password\":\"wrong\"}")).andExpect(status().isUnauthorized());var result=mvc.perform(post("/api/v1/session").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin@biopulse.local\",\"password\":\"IntegrationOnlyPassword!\"}")).andExpect(status().isOk()).andReturn();mvc.perform(get("/api/v1/patients").session((org.springframework.mock.web.MockHttpSession)result.getRequest().getSession())).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].code").value("PT-0247"));}
 @Test @WithMockUser(username="nurse@biopulse.local",roles="NURSE") void roleAndWardAuthorization()throws Exception{mvc.perform(post("/api/v1/devices").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"serial\":\"denied\",\"adapterType\":\"ECG\"}")).andExpect(status().isForbidden());long ward=sql.insert("INSERT INTO wards(name) VALUES(?)","Restricted "+UUID.randomUUID());long bed=sql.insert("INSERT INTO beds(ward_id,label) VALUES(?,'1')",ward);long p=registry.createPatient(new PatientCreate("X"+UUID.randomUUID(),"Restricted",null)).id();long a=registry.createAdmission(new AdmissionCreate(p,bed)).id();mvc.perform(get("/api/v1/admissions/"+a+"/measurements/latest")).andExpect(status().isForbidden());mvc.perform(get("/api/v1/patients/"+p)).andExpect(status().isForbidden());}
 @Test @WithMockUser(username="admin@biopulse.local",roles="ADMIN") void jdbcBatchPipelineDuplicateAndAlertTransitions()throws Exception{
  var source=registry.createSource(new SourceCreate("Test",SourceType.DEVICE,"Integration fixture"));Instant t=Instant.now().minusSeconds(40);var rule=alerts.createRule(new RuleCreate(1,MeasurementCode.TEMP,null,40d,20,15,AlertSeverity.WARNING));List<Observation> rows=new ArrayList<>();for(int sec:List.of(0,10,20))rows.add(new Observation(UUID.randomUUID().toString(),1,1,MeasurementCode.TEMP,41d,"Cel",t.plusSeconds(sec),source.id(),null,QualityFlag.GOOD));ingestion.ingest(rows);
  var history=measurements.history(1,MeasurementCode.TEMP,t,t.plusSeconds(30),100,0);assertEquals(3,history.size());assertEquals(41,history.getFirst().value());assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->ingestion.ingest(rows));assertEquals(3,measurements.history(1,MeasurementCode.TEMP,t,t.plusSeconds(30),100,0).size());var alert=alertDao.active(rule.id()).orElseThrow();assertEquals(AlertState.OPEN,alert.state());var ack=alerts.transition(alert.id(),0,AlertState.ACKNOWLEDGED);assertEquals(1,ack.version());assertThrows(RuntimeException.class,()->alerts.transition(alert.id(),0,AlertState.RESOLVED));assertEquals(AlertState.RESOLVED,alerts.transition(alert.id(),1,AlertState.RESOLVED).state());assertEquals(3,alertDao.events(alert.id()).size());
  mvc.perform(get("/api/v1/admissions/1/analytics").param("from",t.toString()).param("to",t.plusSeconds(30).toString()).param("metric","TEMP")).andExpect(status().isOk()).andExpect(jsonPath("$.summary.count").value(3));
  mvc.perform(post("/api/v1/internal/simulator/measurements").with(csrf()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(List.of(new Observation("bad",1,1,MeasurementCode.HR,null,"bpm",t,source.id(),null,QualityFlag.GOOD))))).andExpect(status().isBadRequest());
 }
 @Test @WithMockUser(username="admin@biopulse.local",roles="ADMIN") void simulationPreservesRecordingTimeAndProvenance(){var session=simulations.create(new SimulationCreate(1,1,1));assertEquals(SimulatorState.CREATED,session.state());simulations.transition(session.id(),"start");simulations.tick(session.id());var output=registry.recording(session.outputRecordingId()).orElseThrow();var rows=measurements.recordingMeasurements(output.id(),Instant.parse("2026-10-25T08:30:00Z"),Instant.parse("2026-10-25T08:30:02Z"),100);assertFalse(rows.isEmpty());assertEquals(Instant.parse("2026-10-25T08:30:00Z"),rows.getFirst().observedAt());assertEquals(SourceType.SIMULATION,registry.source(rows.getFirst().sourceId()).orElseThrow().type());simulations.transition(session.id(),"pause");assertThrows(RuntimeException.class,()->simulations.transition(session.id(),"start"));simulations.transition(session.id(),"resume");simulations.transition(session.id(),"stop");assertEquals(SimulatorState.STOPPED,simulations.get(session.id()).state());}
 @Test @WithMockUser(username="admin@biopulse.local",roles="ADMIN") void reportAndPaginationAndCsrf()throws Exception{mvc.perform(get("/api/v1/alerts").param("size","2")).andExpect(status().isOk()).andExpect(jsonPath("$.items.length()").value(2)).andExpect(jsonPath("$.hasNext").value(true));mvc.perform(post("/api/v1/reports").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"admissionId\":1,\"from\":\"2026-10-25T08:30:00Z\",\"to\":\"2026-10-25T08:38:01Z\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.id").isNumber());mvc.perform(post("/api/v1/patients").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());mvc.perform(get("/api/v1/patients").param("size","-1")).andExpect(status().isBadRequest());}
}
